SELECT num, title, writer, member_num,content,fdate,row_num FROM ( SELECT num, title, writer, member_num,content,fdate,ROW_NUMBER() OVER(ORDER BY num desc) AS row_num FROM faq
writer like '%' || #{searchValue} ||'%'
title like '%' || #{searchValue} ||'%'
content like '%' || #{searchValue} ||'%'
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}
